import{z as o,x as B,o as t,c as d,q as s,j as i,D as e,d as r,s as l,S as n,b as E}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"亚稳态与同步器","description":"","frontmatter":{"title":"亚稳态与同步器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/metastability.md","filePath":"cs/metastability.md","lastUpdated":1791063341000}'),p={name:"cs/metastability.md"};function F(D,a,m,h,u,C){const A=B("Mermaid");return t(),d("div",null,[a[2]||(a[2]=s('<h1 id="亚稳态与同步器" tabindex="-1">亚稳态与同步器 <a class="header-anchor" href="#亚稳态与同步器" aria-label="Permalink to &quot;亚稳态与同步器&quot;">​</a></h1><div class="epigraph"><p>建立保持规定了合法窗口；窗口外采样时 Q 可能停在中间电压，停留时间没有上界，只能谈概率。</p><footer>—— 据 Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p>上一课<a href="/cs/setup-hold">建立保持时间</a>写出了 \\(T\\) 与保持的不等式。不等式满足时，当拍 Q 是合法比特。本课不重推那两条，也不从噪声谱另起。缺口是：异步输入、复位释放、跨时钟，<strong>无法</strong>静态保证窗口；必须承认亚稳，并用同步器把逃逸概率压下去。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>双稳态在中间是不稳定平衡。D 在边沿附近变，触发器可能长时间既非 0 也非 1，下游当 0 和当 1 的门会拆开。解析时间大致指数变好，\\(P(\\mathrm{fail})\\propto e^{-t/\\tau}\\)。缺口是工程含义：多等一拍（再插一级 FF）让亚稳在中间级衰减，而不是「再等两拍数据就对」。</p><p><span class="marginnote">直觉类比：把触发器想象成竖在两谷之间的山顶上的小球——稳稳落在谷里才是 0 或 1；恰好在山顶那一刻采样，小球可能晃很久才掉向一边，掉向哪边连它自己都定不了，这就是亚稳。</span></p><p>同步器：两级（或更多）同域 FF 串起来采样异步信号。MTBF 可算到很大，不是无穷。</p><p><span class="marginnote">数字实例：若解析时间常数 \\(\\tau = 0.2\\) ns，多给 2 ns 解析时间，失败概率就乘上 \\(e^{-10}\\)，约缩到两万分之一；再加一级 FF 再乘同样的因子——「打两拍」不是玄学，是把 MTBF 从几小时推到远超设备寿命的指数杠杆。</span></p><h3 id="同步器不是功能延时器" tabindex="-1">同步器不是功能延时器 <a class="header-anchor" href="#同步器不是功能延时器" aria-label="Permalink to &quot;同步器不是功能延时器&quot;">​</a></h3><p>它不保证「第二拍一定是正确的那位电平」，只保证「第二拍仍非法的概率极低」。把 CDC 当「打两拍的 FIFO」，多比特会撕裂——<a href="/cs/clock-domain">时钟域</a>再收；本课先钉单比特亚稳。</p><p><span class="marginnote">Harris 给出亚稳窗口与解析时间常数。本课不把 \\(\\tau\\) 拟合成工艺作业。寄存器堆、ALU 之间的同步路径应用上一课不等式，不走同步器。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>能静态时序的路径：满足 \\(t_{su}\\)/\\(t_h\\)，不要同步器。不能的：标识为异步，插入 \\(\\ge 2\\) 级 FF，禁止在第一级 Q 上做组合再送第二级以外的逻辑（组合会吃掉解析时间）。</p>',13)),(t(),i(n,null,{default:e(()=>[l(A,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ASYNC%5B%22%E7%AA%97%E5%8F%A3%E6%97%A0%E6%B3%95%E4%BF%9D%E8%AF%81%E7%9A%84%E8%BE%93%E5%85%A5%22%5D%20--%3E%20FF1%5B%22%E7%AC%AC%E4%B8%80%E7%BA%A7%E5%8F%AF%E8%83%BD%E4%BA%9A%E7%A8%B3%22%5D%0A%20%20FF1%20--%3E%20FF2%5B%22%E7%AC%AC%E4%BA%8C%E7%BA%A7%E5%86%8D%E9%87%87%E6%A0%B7%22%5D%0A%20%20FF2%20--%3E%20SAFE%5B%22%E9%80%83%E9%80%B8%E6%A6%82%E7%8E%87%E6%8C%87%E6%95%B0%E4%B8%8B%E9%99%8D%22%5D%0A%20%20SAFE%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E5%A4%9A%E6%AF%94%E7%89%B9%E5%AF%84%E5%AD%98%E5%99%A8%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[r("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"后课寄存器是并排 D，内部同步。与按钮、外设时钟、另一 PLL 的交叉才用本课。单周期教学 CPU 常假装外设已同步；组成主干记得：未同步输入可以直接破坏精确状态。",-1)),a[5]||(a[5]=E("p",null,"复位释放靠近边沿等于异步 D，释放也要同步。",-1)),a[6]||(a[6]=E("p",null,[E("span",{class:"marginnote"},"常见误区：把多比特总线直接「打两拍」就当跨域完成。两级 FF 只压低单比特的亚稳概率；多位信号各比特解析时刻不同，会被撕成「一半新一半旧」的混合值——多比特要握手或异步 FIFO，时钟域课再收。")],-1)),(t(),i(n,null,{default:e(()=>[l(A,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E4%B8%80%E6%9D%A1%20D%20%E8%BE%93%E5%85%A5%E8%B7%AF%E5%BE%84%22%5D%20--%3E%20SAME%7B%22D%20%E4%B8%8E%E9%87%87%E6%A0%B7%E6%97%B6%E9%92%9F%E5%90%8C%E6%BA%90%E5%90%97%3F%22%7D%0A%20%20SAME%20--%3E%7C%22%E5%90%8C%E5%9F%9F%22%7C%20STA%5B%22%E7%94%A8%E5%BB%BA%E7%AB%8B%E4%BF%9D%E6%8C%81%E4%B8%8D%E7%AD%89%E5%BC%8F%E9%9D%99%E6%80%81%E6%A3%80%E6%9F%A5%22%5D%0A%20%20STA%20--%3E%20OK%5B%22%E6%BB%A1%E8%B6%B3%E5%88%99%E5%BD%93%E6%8B%8D%E5%90%88%E6%B3%95%2C%20%E4%B8%8D%E6%8F%92%E5%90%8C%E6%AD%A5%E5%99%A8%22%5D%0A%20%20SAME%20--%3E%7C%22%E5%BC%82%E6%AD%A5%22%7C%20SYNC%5B%22%E6%8F%92%E5%85%A5%E4%B8%A4%E7%BA%A7%E4%BB%A5%E4%B8%8A%20FF%20%E5%90%8C%E6%AD%A5%E5%99%A8%22%5D%0A%20%20SYNC%20--%3E%20PROB%5B%22%E6%8E%A5%E5%8F%97%E6%AE%8B%E4%BD%99%E6%A6%82%E7%8E%87%2C%20%E6%8A%8A%20MTBF%20%E5%8E%8B%E5%88%B0%E6%9E%81%E5%A4%A7%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=s('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲 PLL 锁定检测、不把全异步握手流水线当默认。不讨论量子或模拟比较器亚稳的另一套公式。</p><p>后课默认：同域路径靠建立保持；异步边沿靠同步器降概率。多比特交叉下一课之后的时钟域课才用 FIFO/握手。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>窗口违规可导致亚稳，解析无上界、有概率。</li><li>两级同步器压低逃逸，不是功能必对。</li><li>同步设计内部仍用上一课不等式，不要滥用同步器。</li><li>出处：Harris and Harris。</li></ul>',5))])}const _=o(p,[["render",F]]);export{f as __pageData,_ as default};
